'farmers', 'CREATE TABLE `farmers` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `farmer_code` varchar(30) NOT NULL,\n  `name` varchar(150) NOT NULL,\n  `phone` varchar(20) DEFAULT NULL,\n  `village` varchar(100) DEFAULT NULL,\n  `address` text,\n  `active` tinyint(1) NOT NULL DEFAULT \'1\',\n  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,\n  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `uq_farmer_code_family` (`family_id`,`farmer_code`),\n  KEY `idx_farmers_family_name` (`family_id`,`name`),\n  CONSTRAINT `farmers_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'

'families', 'CREATE TABLE `families` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_name` varchar(120) NOT NULL,\n  `invite_code` varchar(32) NOT NULL,\n  `active` tinyint(1) NOT NULL DEFAULT \'1\',\n  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `invite_code` (`invite_code`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'


'work_entries', 'CREATE TABLE `work_entries` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `farmer_id` bigint NOT NULL,\n  `work_type_id` bigint DEFAULT NULL,\n  `work_date` date NOT NULL,\n  `location` varchar(200) DEFAULT NULL,\n  `quantity_description` varchar(200) DEFAULT NULL,\n  `total_amount` decimal(12,2) NOT NULL DEFAULT \'0.00\',\n  `notes` text,\n  `billing_status` varchar(20) NOT NULL DEFAULT \'UNBILLED\',\n  `verification_status` varchar(20) NOT NULL DEFAULT \'PENDING\',\n  `created_by` bigint NOT NULL,\n  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,\n  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,\n  `version` bigint NOT NULL DEFAULT \'0\',\n  PRIMARY KEY (`id`),\n  KEY `work_type_id` (`work_type_id`),\n  KEY `created_by` (`created_by`),\n  KEY `idx_work_family_date` (`family_id`,`work_date`),\n  KEY `idx_work_farmer_date` (`farmer_id`,`work_date`),\n  KEY `idx_work_billing` (`family_id`,`billing_status`,`work_date`),\n  CONSTRAINT `work_entries_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`),\n  CONSTRAINT `work_entries_ibfk_2` FOREIGN KEY (`farmer_id`) REFERENCES `farmers` (`id`),\n  CONSTRAINT `work_entries_ibfk_3` FOREIGN KEY (`work_type_id`) REFERENCES `work_types` (`id`),\n  CONSTRAINT `work_entries_ibfk_4` FOREIGN KEY (`created_by`) REFERENCES `app_users` (`id`),\n  CONSTRAINT `work_entries_chk_1` CHECK ((`total_amount` >= 0))\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'

'invoices', 'CREATE TABLE `invoices` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `farmer_id` bigint NOT NULL,\n  `invoice_number` varchar(40) NOT NULL,\n  `invoice_date` date NOT NULL,\n  `due_date` date NOT NULL,\n  `total_amount` decimal(12,2) NOT NULL,\n  `status` varchar(20) NOT NULL DEFAULT \'ISSUED\',\n  `notes` text,\n  `created_by` bigint NOT NULL,\n  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `uq_invoice_number_family` (`family_id`,`invoice_number`),\n  KEY `created_by` (`created_by`),\n  KEY `idx_invoice_due` (`family_id`,`due_date`,`status`),\n  KEY `idx_invoice_farmer_date` (`farmer_id`,`invoice_date`),\n  CONSTRAINT `invoices_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`),\n  CONSTRAINT `invoices_ibfk_2` FOREIGN KEY (`farmer_id`) REFERENCES `farmers` (`id`),\n  CONSTRAINT `invoices_ibfk_3` FOREIGN KEY (`created_by`) REFERENCES `app_users` (`id`),\n  CONSTRAINT `invoices_chk_1` CHECK ((`total_amount` >= 0))\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'

'work_types', 'CREATE TABLE `work_types` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `name` varchar(100) NOT NULL,\n  `active` tinyint(1) NOT NULL DEFAULT \'1\',\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `uq_work_type_family` (`family_id`,`name`),\n  CONSTRAINT `work_types_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'


'app_users', 'CREATE TABLE `app_users` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `full_name` varchar(120) NOT NULL,\n  `email` varchar(190) NOT NULL,\n  `password_hash` varchar(255) NOT NULL,\n  `role` varchar(20) NOT NULL,\n  `membership_status` varchar(20) NOT NULL,\n  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `email` (`email`),\n  KEY `idx_users_family` (`family_id`),\n  CONSTRAINT `fk_users_family` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'

'audit_logs', 'CREATE TABLE `audit_logs` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `actor_user_id` bigint DEFAULT NULL,\n  `action` varchar(40) NOT NULL,\n  `entity_type` varchar(60) NOT NULL,\n  `entity_id` bigint DEFAULT NULL,\n  `details` json DEFAULT NULL,\n  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (`id`),\n  KEY `actor_user_id` (`actor_user_id`),\n  KEY `idx_audit_family_time` (`family_id`,`created_at`),\n  CONSTRAINT `audit_logs_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`),\n  CONSTRAINT `audit_logs_ibfk_2` FOREIGN KEY (`actor_user_id`) REFERENCES `app_users` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'

'invoice_items', 'CREATE TABLE `invoice_items` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `invoice_id` bigint NOT NULL,\n  `work_entry_id` bigint NOT NULL,\n  `description` varchar(255) DEFAULT NULL,\n  `amount` decimal(12,2) NOT NULL,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `uq_invoice_work` (`invoice_id`,`work_entry_id`),\n  UNIQUE KEY `uq_work_billed` (`work_entry_id`),\n  KEY `family_id` (`family_id`),\n  CONSTRAINT `invoice_items_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`),\n  CONSTRAINT `invoice_items_ibfk_2` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`id`),\n  CONSTRAINT `invoice_items_ibfk_3` FOREIGN KEY (`work_entry_id`) REFERENCES `work_entries` (`id`),\n  CONSTRAINT `invoice_items_chk_1` CHECK ((`amount` >= 0))\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'

'payment_allocations', 'CREATE TABLE `payment_allocations` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `payment_id` bigint NOT NULL,\n  `invoice_id` bigint NOT NULL,\n  `allocated_amount` decimal(12,2) NOT NULL,\n  PRIMARY KEY (`id`),\n  KEY `family_id` (`family_id`),\n  KEY `idx_alloc_invoice` (`invoice_id`),\n  KEY `idx_alloc_payment` (`payment_id`),\n  CONSTRAINT `payment_allocations_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`),\n  CONSTRAINT `payment_allocations_ibfk_2` FOREIGN KEY (`payment_id`) REFERENCES `payments` (`id`),\n  CONSTRAINT `payment_allocations_ibfk_3` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`id`),\n  CONSTRAINT `payment_allocations_chk_1` CHECK ((`allocated_amount` > 0))\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'

'payments', 'CREATE TABLE `payments` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `farmer_id` bigint NOT NULL,\n  `payment_date` date NOT NULL,\n  `amount` decimal(12,2) NOT NULL,\n  `payment_mode` varchar(30) NOT NULL,\n  `reference_number` varchar(100) DEFAULT NULL,\n  `idempotency_key` varchar(80) NOT NULL,\n  `notes` text,\n  `created_by` bigint NOT NULL,\n  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `uq_payment_idempotency` (`family_id`,`idempotency_key`),\n  KEY `farmer_id` (`farmer_id`),\n  KEY `created_by` (`created_by`),\n  KEY `idx_payment_farmer_date` (`family_id`,`farmer_id`,`payment_date`),\n  CONSTRAINT `payments_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`),\n  CONSTRAINT `payments_ibfk_2` FOREIGN KEY (`farmer_id`) REFERENCES `farmers` (`id`),\n  CONSTRAINT `payments_ibfk_3` FOREIGN KEY (`created_by`) REFERENCES `app_users` (`id`),\n  CONSTRAINT `payments_chk_1` CHECK ((`amount` > 0))\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'

'work_types', 'CREATE TABLE `work_types` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `family_id` bigint NOT NULL,\n  `name` varchar(100) NOT NULL,\n  `active` tinyint(1) NOT NULL DEFAULT \'1\',\n  PRIMARY KEY (`id`),\n  UNIQUE KEY `uq_work_type_family` (`family_id`,`name`),\n  CONSTRAINT `work_types_ibfk_1` FOREIGN KEY (`family_id`) REFERENCES `families` (`id`)\n) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci'
